<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TanzaniaTrip | Hotels</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.css" rel="stylesheet"><link rel="stylesheet" href="assets/css/tanzania.css"><style>.hotel-hero{min-height:470px;background:linear-gradient(90deg,rgba(3,31,22,.94),rgba(3,31,22,.38)),url('https://images.unsplash.com/photo-1564501049412-61c2a3083791?auto=format&fit=crop&w=2200&q=88') center/cover;color:#fff;display:flex;align-items:end;padding:90px 0}.filterbar{margin-top:-45px;position:relative;z-index:4;background:#fff;border-radius:24px;box-shadow:0 20px 55px rgba(3,31,22,.15);padding:18px}.hotel-card{background:#fff;border-radius:24px;overflow:hidden;box-shadow:0 14px 40px rgba(3,31,22,.09);height:100%;border:1px solid #e5ebe7}.hotel-card img{height:245px;width:100%;object-fit:cover}.room-row{display:flex;gap:8px;flex-wrap:wrap}.room-chip{border:1px solid #cfdcd5;border-radius:30px;padding:7px 11px;font-size:.75rem}.live-dot{width:9px;height:9px;border-radius:50%;background:#25a85a;display:inline-block;box-shadow:0 0 0 5px #25a85a20}.feature-strip{background:#062d20;color:#fff;border-radius:26px;padding:28px}.hotel-action{cursor:pointer}.no-results{display:none}</style></head><body>
