<header class="hotel-hero"><div class="container"><div class="eyebrow">Tanzania hospitality network</div><h1 class="display-2 fw-bold mt-3">Choose a stay by<br><span style="color:#f0ce72">place, room and service.</span></h1><p class="lead mt-3" style="max-width:760px">Search properties, inspect room types, check operational features and move directly into a reservation request.</p></div></header>
<main><div class="container"><div class="filterbar"><div class="row g-2"><div class="col-lg-4"><input id="q" class="form-control form-control-lg" placeholder="Search hotel, city or room type"></div><div class="col-lg-2"><select id="city" class="form-select form-select-lg"><option value="">All cities</option><option>Arusha</option><option>Zanzibar</option><option>Dar es Salaam</option><option>Dodoma</option></select></div><div class="col-lg-2"><select id="kind" class="form-select form-select-lg"><option value="">All stays</option><option>Luxury</option><option>Beach</option><option>City</option></select></div><div class="col-lg-2"><input id="guests" type="number" min="1" value="2" class="form-control form-control-lg" placeholder="Guests"></div><div class="col-lg-2"><button id="find" class="btn btn-tz btn-lg w-100">Find stays <i class="bi bi-search"></i></button></div></div><div class="small text-secondary mt-3"><span class="live-dot me-2"></span><span id="count">4</span> properties in the current catalogue · live inventory connection ready for provider APIs</div></div></div>
<section class="section"><div class="container"><div class="d-flex justify-content-between align-items-end mb-5"><div><div class="kicker">Hotel catalogue</div><h2>Stays that belong to the journey.</h2></div><a class="btn btn-gold" href="rooms.php">Inspect spaces <i class="bi bi-grid-3x3-gap"></i></a></div><div class="row g-4" id="hotels"><?php foreach($hotels as $i=>$h): ?><div class="col-lg-6 hotel-item" data-search="<?=strtolower($h['name'].' '.$h['city'].' '.$h['type'].' '.implode(' ',$h['rooms']))?>" data-city="<?=$h['city']?>" data-kind="<?=strtolower($h['type'])?>"><article class="hotel-card"><img src="<?=$h['img']?>" alt="<?=htmlspecialchars($h['name'])?>"><div class="p-4"><div class="d-flex justify-content-between gap-2"><span class="badge text-bg-success"><?=$h['city']?></span><span class="small text-secondary">★★★★★</span></div><h3 class="mt-3 mb-1"><?=htmlspecialchars($h['name'])?></h3><p class="text-secondary mb-3"><?=htmlspecialchars($h['type'])?></p><div class="room-row mb-3"><?php foreach($h['rooms'] as $r): ?><span class="room-chip"><i class="bi bi-door-open me-1"></i><?=$r?></span><?php endforeach; ?></div><div class="d-flex flex-wrap gap-3 small text-secondary mb-4"><span><i class="bi bi-wifi me-1"></i><?=$h['wifi']?></span><span><i class="bi bi-shield-check me-1"></i><?=$h['door']?></span></div><div class="d-flex justify-content-between align-items-center"><strong class="price"><?=$h['price']?></strong><button class="btn btn-gold hotel-action" data-hotel="<?=htmlspecialchars($h['name'])?>">View & request</button></div></div></article></div><?php endforeach; ?></div><div class="no-results text-center py-5" id="none"><h3>No matching property</h3><p class="text-secondary">Change the city, category or search term.</p></div></div></section>
<section class="section pt-0"><div class="container"><div class="feature-strip"><div class="row g-4 align-items-center"><div class="col-lg-7"><div class="kicker" style="color:#f0ce72">Hotel operating layer</div><h2 class="text-white mt-2">A hotel is more than a room card.</h2><p class="text-white-50 mb-0">The platform is structured to connect rooms, occupancy, Wi‑Fi health, smart doors, guest requests, transfers and reservation status.</p></div><div class="col-lg-5"><div class="row g-2"><div class="col-6"><div class="bg-white text-dark rounded-4 p-3"><small>Rooms</small><strong class="d-block">Inventory</strong></div></div><div class="col-6"><div class="bg-white text-dark rounded-4 p-3"><small>Network</small><strong class="d-block">Wi‑Fi health</strong></div></div><div class="col-6"><div class="bg-white text-dark rounded-4 p-3"><small>Access</small><strong class="d-block">Door status</strong></div></div><div class="col-6"><div class="bg-white text-dark rounded-4 p-3"><small>Guests</small><strong class="d-block">Requests</strong></div></div></div></div></div></div></div></section></main>
<div class="modal fade" id="hotelModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content rounded-4 border-0"><div class="modal-header"><h5 class="modal-title">Reservation request</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="fw-bold fs-5" id="modalHotel"></div><p class="text-secondary">No payment is taken here. Submit your stay requirements for the booking layer.</p><div class="row g-2"><div class="col-6"><input class="form-control" type="date"></div><div class="col-6"><input class="form-control" type="date"></div><div class="col-6"><input class="form-control" placeholder="Full name"></div><div class="col-6"><input class="form-control" placeholder="Phone / WhatsApp"></div></div></div><div class="modal-footer"><button class="btn btn-tz" data-bs-dismiss="modal">Send request</button></div></div></div></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>const items=[...document.querySelectorAll('.hotel-item')];function filter(){const q=document.querySelector('#q').value.toLowerCase(),c=document.querySelector('#city').value,k=document.querySelector('#kind').value.toLowerCase();let n=0;items.forEach(x=>{const ok=x.dataset.search.includes(q)&&(!c||x.dataset.city===c)&&(!k||x.dataset.kind.includes(k));x.style.display=ok?'block':'none';if(ok)n++});document.querySelector('#count').textContent=n;document.querySelector('#none').style.display=n?'none':'block'}document.querySelector('#find').onclick=filter;['q','city','kind'].forEach(id=>document.querySelector('#'+id).addEventListener('input',filter));document.querySelectorAll('.hotel-action').forEach(b=>b.onclick=()=>{document.querySelector('#modalHotel').textContent=b.dataset.hotel;new bootstrap.Modal('#hotelModal').show()});</script></body></html>